<?php get_header(); $artists=get_terms(array('taxonomy'=>'gmr_artist','hide_empty'=>false,'exclude'=>array(($anon=get_term_by('slug','anonimo','gmr_artist'))?$anon->term_id:0)));$artists=is_wp_error($artists)?array():gmr_theme_order_terms($artists,'gmr_artist_order'); ?>
<header class="gmr-archive-head"><div class="gmr-wrap"><span class="gmr-kicker">Voces y trayectorias</span><h1 class="gmr-page-title">Artistas</h1><p>Una comunidad de creadores modernos y contemporaneos vinculados a la historia de la galeria.</p></div></header>
<section class="gmr-section"><div class="gmr-wrap gmr-people-grid"><?php foreach($artists as $artist):$portrait=absint(get_term_meta($artist->term_id,'gmr_artist_portrait_id',true));$cover=absint(get_term_meta($artist->term_id,'gmr_artist_cover_id',true));?><article class="gmr-person"><a href="<?php echo esc_url(get_term_link($artist));?>"><div class="gmr-person__image"><?php echo wp_get_attachment_image($portrait?:$cover,'large'); ?></div><span class="gmr-kicker"><?php echo esc_html($artist->count.' obras');?></span><h2><?php echo esc_html($artist->name);?></h2></a></article><?php endforeach;?></div></section><?php get_footer();?>
